      "lyrics": [
        "同じように求めてしまうから",
        "黙って居ればいい？",
        "望むように逆さに歩いてく",
        "息絶えたみたいだ"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "潜在的な憂いには",
        "如何にも素直になれず",
        "誰とも訳合えないね",
        "自分さえも"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "命令　故意を感じて",
        "訂正　無為を観じて",
        "安寧は罪が混ざる",
        "当然か"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "知った顔で笑っててよ",
        "底知らず恐れるの",
        "月並みの愛をくれよ",
        "You know me",
        "知った気で踊ってるの",
        "底が満たされるの",
        "放さないで止めないで",
        "独りじゃないの"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
