      "id": "B1-04",
      "ja": "当然か",
      "budget": {
        "min": 3,
        "max": 3
      },
      "pattern": [
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "命令 察觉到故意"
        },
        {
          "id": "B1-02",
          "zh": "订正 凝视着无为"
        },
        {
          "id": "B1-03",
          "zh": "安宁里 掺着罪意"
        },
        {
          "id": "B1-04",
          "zh": "理所当然"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "命令　感到故意"
        },
        {
          "id": "B1-02",
          "zh": "订正　观察无为"
        },
        {
          "id": "B1-03",
          "zh": "安宁混入了罪"
        },
        {
          "id": "B1-04",
          "zh": "理所当然吗"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "命令 字里带刺 扎人"
        },
        {
          "id": "B1-02",
          "zh": "订正 划掉所有 可能"
        },
        {
          "id": "B1-03",
          "zh": "安宁 底下掺进 一点罪"
        },
        {
          "id": "B1-04",
          "zh": "当然吧"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "命令 故意地感受"
        },
        {
          "id": "B1-02",
          "zh": "订正 无为地观透"
        },
        {
          "id": "B1-03",
          "zh": "安宁之中掺杂罪"
        },
        {
          "id": "B1-04",
          "zh": "当然吗"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "命令 咬住那点 敌意"
        },
        {
          "id": "B1-02",
          "zh": "订正 旁观那团 虚无"
        },
        {
          "id": "B1-03",
          "zh": "安宁 掺一点罪 才完整"
        },
        {
          "id": "B1-04",
          "zh": "当然吧"
        }
      ]
    }
  ]
}

